        group.MapPost("/price-lists", async (CreatePriceListRequest request, HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, PricingService service, CancellationToken ct) => await Authorized(http, subjects, authorizer, "pricing.list.manage", request.LegalEntityId, ct) is { Allowed: true } access ? await Execute(() => service.CreateListAsync(access.Tenant, access.ActorId, access.MembershipId, request, Correlation(http), ct), StatusCodes.Status201Created) : Results.Forbid()).Produces<PriceListDto>(StatusCodes.Status201Created);
        group.MapPost("/price-lists/{listId:guid}/versions", async (Guid listId, Guid legalEntityId, CreatePriceVersionRequest request, HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, PricingService service, CancellationToken ct) => await Authorized(http, subjects, authorizer, "pricing.version.create", legalEntityId, ct) is { Allowed: true } access ? await Execute(() => service.CreateVersionAsync(access.Tenant, legalEntityId, access.ActorId, access.MembershipId, listId, request, Correlation(http), ct), StatusCodes.Status201Created) : Results.Forbid()).Produces<PriceVersionDto>(StatusCodes.Status201Created);
        group.MapGet("/price-lists/{listId:guid}/versions", async (Guid listId, Guid legalEntityId, HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, PricingService service, CancellationToken ct) => await Authorized(http, subjects, authorizer, "pricing.read", legalEntityId, ct) is { Allowed: true } access ? await Execute(() => service.ListVersionsAsync(access.Tenant, legalEntityId, listId, ct)) : Results.Forbid()).Produces<IReadOnlyList<PriceVersionDto>>();
        group.MapGet("/price-lists/{listId:guid}/versions/{versionId:guid}/entries", async (Guid listId, Guid versionId, Guid legalEntityId, int? page, int? pageSize, HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, PricingService service, CancellationToken ct) => await Authorized(http, subjects, authorizer, "pricing.read", legalEntityId, ct) is { Allowed: true } access ? await Execute(() => service.ListVersionContentAsync(access.Tenant, legalEntityId, listId, versionId, page ?? 1, pageSize ?? 50, ct)) : Results.Forbid()).Produces<PriceVersionContentPageDto>();
        group.MapPost("/versions/{versionId:guid}/entries", async (Guid versionId, Guid listId, Guid legalEntityId, CreatePriceEntryRequest request, HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, PricingService service, CancellationToken ct) => await Authorized(http, subjects, authorizer, "pricing.rule.manage", legalEntityId, ct) is { Allowed: true } access ? await Execute(async () => { await service.AddEntryAsync(access.Tenant, legalEntityId, access.ActorId, access.MembershipId, listId, versionId, request, Correlation(http), ct); return new { versionId }; }, StatusCodes.Status201Created) : Results.Forbid());
        group.MapPost("/versions/{versionId:guid}/rules", async (Guid versionId, Guid listId, Guid legalEntityId, CreatePriceRuleRequest request, HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, PricingService service, CancellationToken ct) => await Authorized(http, subjects, authorizer, "pricing.rule.manage", legalEntityId, ct) is { Allowed: true } access ? await Execute(async () => { await service.AddRuleAsync(access.Tenant, legalEntityId, access.ActorId, access.MembershipId, listId, versionId, request, Correlation(http), ct); return new { versionId }; }, StatusCodes.Status201Created) : Results.Forbid());
