        group.MapPost("/imports/{batchId:guid}/commit", async (Guid batchId, Guid legalEntityId, HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, PricingService service, CancellationToken ct) => await Authorized(http, subjects, authorizer, "pricing.import", legalEntityId, ct) is { Allowed: true } access ? await Execute(() => service.CommitImportAsync(access.Tenant, access.ActorId, access.MembershipId, batchId, Correlation(http), ct)) : Results.Forbid());
