        group.MapGet("/coverage", async (Guid legalEntityId, Guid priceListId, DateOnly pricingDate, HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, PricingService service, CancellationToken ct) => await Authorized(http, subjects, authorizer, "pricing.read", legalEntityId, ct) is { Allowed: true } access ? await Execute(() => service.GetCoverageAsync(access.Tenant, legalEntityId, priceListId, pricingDate, ct)) : Results.Forbid());
        group.MapPost("/simulate", async (ResolvePriceRequest request, HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, PricingService service, CancellationToken ct) => await Authorized(http, subjects, authorizer, "pricing.simulate", request.LegalEntityId, ct) is { Allowed: true } access ? await Execute(() => service.ResolveAsync(ToContext(access.Tenant, request), ct)) : Results.Forbid());
        group.MapPost("/explain", async (ResolvePriceRequest request, HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, PricingService service, CancellationToken ct) => await Authorized(http, subjects, authorizer, "pricing.read", request.LegalEntityId, ct) is { Allowed: true } access ? await Execute(() => service.ResolveAsync(ToContext(access.Tenant, request), ct)) : Results.Forbid());
